#!/usr/bin/env bash
# 强制重跑依赖图里全部 tauri 插件的 build script —— CI 必需的一步「防腐」。
#
# 为什么需要（2026-10-17 dev 内容 CI 验证实测的两处红，同源）：
# tauri 插件把「权限清单文件路径」经 `links` + build script 输出暴露给宿主 build.rs
# （宿主侧 tauri-utils 的 `read_permissions()` 遍历 `DEP_<PLUGIN>_PERMISSION_FILES_PATH`
# 环境变量收集）；另有部分插件的 `permissions/autogenerated/**` 就是**插件自身 build.rs
# 生成**的，直接写进 cargo registry 源码目录（上游 .crate 不含这些文件，例如
# tauri-plugin-edge-to-edge 0.3.3 只发布了 permissions/default.toml）。
#
# 而 rust-cache 只缓存 target/：
#   - 插件的 build script 指纹被恢复为 fresh ⇒ 插件 build script 不再重跑；
#   - `~/.cargo/registry/src` 每次重新解包（不含生成物）。
# 两者叠加后宿主 tauri-build 收集不到该插件权限、或读不到生成物，报：
#   - 桌面（Windows 实测）`Permission wdio:default not found, expected one of core:default, ...`
#   - 移动（Linux 实测）`failed to read plugin permissions ... permissions/autogenerated/commands/disable.toml: No such file or directory`
#
# 修法：清掉依赖图里每个 tauri 插件包（`cargo clean -p`）——指纹与产物一并移除，
# 下次构建强制其 build script 重跑，DEP_* 与生成物同时重建。每包数秒级，依赖树不受影响。
#
# 用法：scripts/refresh-tauri-plugin-permissions.sh [--dry-run] <app 目录>
#   <app 目录> 含 Cargo.toml 的应用目录（如 bedcode-desktop/src-tauri、cross-end-tests）
#
# 注意：本脚本只做「清理」，**绝不解析/改写依赖**——所有 cargo 调用带 `--locked`。
# 不带 `--locked` 时，缓存恢复后 cargo 会重建索引并重解析（CI 实测：`cargo tree` 把
# lock 里的 `tauri` 2.11.1 升到 2.12.4），而 JS 侧 `@tauri-apps/*` 由 pnpm lock 固定在
# 2.11.x → tauri-cli 的「Rust crate ↔ JS 包 版本一致性」检查直接把构建卡死。
set -euo pipefail

dry_run=0
if [ "${1:-}" = "--dry-run" ]; then
  dry_run=1
  shift
fi

app_dir="${1:-}"
if [ -z "$app_dir" ]; then
  echo "用法: $0 [--dry-run] <app 目录>（含 Cargo.toml，如 bedcode-desktop/src-tauri）" >&2
  exit 2
fi
if [ ! -f "$app_dir/Cargo.toml" ]; then
  echo "[refresh-tauri-plugin-permissions] $app_dir 下没有 Cargo.toml" >&2
  exit 2
fi
cd "$app_dir"

# 只读守护：本步骤只允许删产物，不得碰 Cargo.lock（见头部注释）。
lock_before="$(sha256sum Cargo.lock 2>/dev/null | cut -d' ' -f1 || true)"

# 取**当前平台/feature 实际依赖图**里的插件（不是 lock 全量：平台专属插件不在图里时
# `cargo clean -p` 会报 "did not match any packages"）。用 name@version 规格避免同名多版本歧义。
mapfile -t specs < <(
  cargo tree --locked --prefix none 2>/dev/null |
    awk '/^tauri-plugin-/ {print $1 "@" substr($2, 2)}' |
    sort -u
)

if [ "${#specs[@]}" -eq 0 ]; then
  echo "[refresh-tauri-plugin-permissions] $app_dir 的依赖图里没有 tauri 插件，跳过"
  exit 0
fi

for spec in "${specs[@]}"; do
  if [ "$dry_run" = "1" ]; then
    echo "cargo clean --locked -p $spec"
  else
    cargo clean --locked -p "$spec"
  fi
done

if [ "$dry_run" != "1" ]; then
  lock_after="$(sha256sum Cargo.lock 2>/dev/null | cut -d' ' -f1 || true)"
  if [ "$lock_before" != "$lock_after" ]; then
    echo "[refresh-tauri-plugin-permissions] ::error::Cargo.lock 被本步骤改写了（本步骤只应清理产物）；请确认 cargo 调用带 --locked" >&2
    exit 1
  fi
fi
echo "[refresh-tauri-plugin-permissions] $app_dir：已刷新 ${#specs[@]} 个插件包（${specs[*]}）"
